package com.seminarhub.domain.seminar.service;
import com.seminarhub.domain.seminar.domain.MemberSeminar; import com.seminarhub.domain.seminar.domain.MemberSeminarSettlementDate; import com.seminarhub.domain.seminar.repository.MemberSeminarSettlementDateRepository; import com.seminarhub.global.dto.CursorRequest;
import java.time.LocalDate; import java.util.List; import java.util.Optional; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class MemberSeminarSettlementDateService { private final MemberSeminarSettlementDateRepository repository;
@Transactional public MemberSeminarSettlementDate save(MemberSeminarSettlementDate e){return repository.save(e);} public Optional<MemberSeminarSettlementDate> findById(Long id){return repository.findByIdAndDeletedAtIsNull(id);} public List<MemberSeminarSettlementDate> findByIds(List<Long> ids){return repository.findAllByIdInAndDeletedAtIsNull(ids);} public List<MemberSeminarSettlementDate> findAll(MemberSeminarSettlementDateSearchQuery q){return repository.search(q);} public Page<MemberSeminarSettlementDate> findAll(MemberSeminarSettlementDateSearchQuery q,Pageable p){return repository.search(q,p);} public List<MemberSeminarSettlementDate> findByCursor(MemberSeminarSettlementDateSearchQuery q,CursorRequest c){return repository.search(q,c);} @Transactional public MemberSeminarSettlementDate update(MemberSeminarSettlementDate e,MemberSeminar ms,LocalDate date){e.update(ms,date);return e;} @Transactional public MemberSeminarSettlementDate delete(MemberSeminarSettlementDate e){e.delete();return e;} @Transactional public List<MemberSeminarSettlementDate> deleteAll(List<MemberSeminarSettlementDate> es){es.forEach(MemberSeminarSettlementDate::delete);return es;} }
